import os
import glob
import json
import hashlib
from datetime import datetime, timedelta
from pathlib import Path


class ArtifactTamperError(Exception):
    """Raised when an artifact's integrity check fails due to SHA-256 hash mismatch."""
    pass


class WorkspaceGarbageCollector:
    """
    Manages workspace cleanup, artifact integrity verification, and storage analytics
    while strictly preserving locked baseline reports.
    """

    LOCKED_FILES = {"master_ledger.md"}

    def __init__(self, workspace_dir: str | Path):
        self.workspace_dir = Path(workspace_dir)

    def _is_locked(self, path: Path) -> bool:
        """Determines if a file or directory is part of the locked baseline reports."""
        if path.name in self.LOCKED_FILES or path.name.endswith(".json"):
            return True
        return False

    def verify_artifact_integrity(self) -> None:
        """
        Verifies the integrity of baseline JSON reports by checking them against
        any accompanying SHA-256 checksum files (e.g., filename.json.sha256).
        Raises ArtifactTamperError if a mismatch is detected.
        """
        if not self.workspace_dir.exists():
            return

        # Find all JSON files in the workspace
        json_files = self.workspace_dir.rglob("*.json")
        for json_path in json_files:
            sha_path = Path(str(json_path) + ".sha256")
            if sha_path.exists():
                expected_hash = sha_path.read_text(encoding="utf-8").strip().split()[0]

                sha256_hash = hashlib.sha256()
                with open(json_path, "rb") as f:
                    for byte_block in iter(lambda: f.read(4096), b""):
                        sha256_hash.update(byte_block)
                actual_hash = sha256_hash.hexdigest()

                if actual_hash != expected_hash:
                    raise ArtifactTamperError(
                        f"Integrity check failed for {json_path.name}: "
                        f"Expected {expected_hash}, got {actual_hash}"
                    )

    def purge_expired_runs(self, max_age_days: int) -> list[str]:
        """
        Purges files and directories older than max_age_days, strictly preserving
        locked baseline reports (master_ledger.md and *.json files).
        Returns a list of paths (as strings) that were purged.
        """
        if not self.workspace_dir.exists():
            return []

        cutoff_time = datetime.now() - timedelta(days=max_age_days)
        purged_paths = []

        # Walk bottom-up so we can remove empty directories as well
        for root, dirs, files in os.walk(self.workspace_dir, topdown=False):
            root_path = Path(root)

            # Process files
            for file in files:
                file_path = root_path / file

                # Never purge locked files
                if self._is_locked(file_path):
                    continue

                # Also skip checksum files for locked json files
                if file_path.name.endswith(".json.sha256"):
                    continue

                try:
                    mtime = datetime.fromtimestamp(file_path.stat().st_mtime)
                    if mtime < cutoff_time:
                        file_path.unlink()
                        purged_paths.append(str(file_path))
                except (PermissionError, FileNotFoundError):
                    continue

            # Process directories (excluding workspace root itself)
            for d in dirs:
                dir_path = root_path / d

                # Check if directory contains or is locked
                if self._is_locked(dir_path):
                    continue

                try:
                    # If directory is empty after file cleanup, check its age or remove it
                    if dir_path.exists() and not any(dir_path.iterdir()):
                        mtime = datetime.fromtimestamp(dir_path.stat().st_mtime)
                        if mtime < cutoff_time:
                            dir_path.rmdir()
                            purged_paths.append(str(dir_path))
                except (PermissionError, FileNotFoundError, OSError):
                    continue

        return purged_paths

    def get_storage_breakdown(self) -> dict[str, int]:
        """
        Returns a dictionary mapping file categories or extensions to their total size in bytes.
        """
        breakdown: dict[str, int] = {}

        if not self.workspace_dir.exists():
            return breakdown

        for path in self.workspace_dir.rglob("*"):
            if path.is_file():
                try:
                    size = path.stat().st_size
                    ext = path.suffix.lower() if path.suffix else "no_extension"
                    breakdown[ext] = breakdown.get(ext, 0) + size
                except (PermissionError, FileNotFoundError):
                    continue

        return breakdown
